        let len_usize = participations.len();
        let n_usize = n as usize;
        let m_usize = if n_usize <= len_usize { n_usize } else { len_usize };

        // i = how many we've processed so far
        // teams = how many full teams of 3 seen among those
        // rem   = how many eligibles modulo 3 seen so far
        let mut i: usize = 0;
        let mut teams: u8 = 0;
